CREATE TABLE outbox_events(id BINARY(16) PRIMARY KEY,event_type VARCHAR(64) NOT NULL,aggregate_type VARCHAR(64) NOT NULL,aggregate_id BINARY(16) NOT NULL,aggregate_version BIGINT UNSIGNED NOT NULL,dedupe_key VARCHAR(191) NOT NULL UNIQUE,payload JSON NOT NULL,status ENUM('PENDING','PUBLISHED') NOT NULL DEFAULT 'PENDING',created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),published_at TIMESTAMP(6),INDEX ix_outbox_status(status,created_at)) ENGINE=InnoDB;
CREATE TABLE transfer_jobs(id BINARY(16) PRIMARY KEY,request_id BINARY(16) NOT NULL,file_id BINARY(16) NOT NULL,source_storage_version_id BINARY(16) NOT NULL,target_storage_version_id BINARY(16) NOT NULL,expected_sha256 BINARY(32) NOT NULL,expected_bytes BIGINT UNSIGNED NOT NULL,candidate_key VARCHAR(512) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,status ENUM('PENDING','RUNNING','SUCCEEDED','FAILED','DEAD','QUARANTINED') NOT NULL DEFAULT 'PENDING',available_at TIMESTAMP(6) NOT NULL,attempts INT UNSIGNED NOT NULL DEFAULT 0,lease_owner VARCHAR(128),lease_token BIGINT UNSIGNED NOT NULL DEFAULT 0,lease_expires_at TIMESTAMP(6),last_error_code VARCHAR(64),last_error_detail VARCHAR(1000),created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY uk_transfer_file(file_id),CONSTRAINT fk_transfer_request FOREIGN KEY(request_id) REFERENCES exchange_requests(id),CONSTRAINT fk_transfer_file FOREIGN KEY(file_id) REFERENCES request_files(id),INDEX ix_transfer_claim(status,available_at,lease_expires_at)) ENGINE=InnoDB;
CREATE TABLE transfer_attempts(id BINARY(16) PRIMARY KEY,transfer_job_id BINARY(16) NOT NULL,attempt_no INT UNSIGNED NOT NULL,fencing_token BIGINT UNSIGNED NOT NULL,worker_instance_id VARCHAR(128) NOT NULL,candidate_key VARCHAR(512) NOT NULL,status ENUM('RUNNING','SUCCEEDED','FAILED','STALE','QUARANTINED') NOT NULL,bytes_copied BIGINT UNSIGNED NOT NULL DEFAULT 0,target_version_id VARCHAR(512),computed_sha256 BINARY(32),started_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),finished_at TIMESTAMP(6),error_code VARCHAR(64),UNIQUE KEY uk_transfer_attempt(transfer_job_id,attempt_no),CONSTRAINT fk_attempt_job FOREIGN KEY(transfer_job_id) REFERENCES transfer_jobs(id)) ENGINE=InnoDB;
ALTER TABLE request_files ADD COLUMN target_object_key VARCHAR(512) CHARACTER SET ascii COLLATE ascii_bin AFTER target_bucket;
INSERT IGNORE INTO role_permissions(role_id,permission) SELECT id,'transfers.read' FROM roles WHERE code='SYSTEM_OPERATOR';
INSERT IGNORE INTO role_permissions(role_id,permission) SELECT id,'transfers.retry' FROM roles WHERE code='SYSTEM_OPERATOR';
